/*
 * library_glue.c - rustsocket.library: the Resident, the manager interface
 * and the per-opener "main" interfaces.
 *
 * Each GetInterface(base, "main", 1) gets an interface of its own (the
 * manager's GetInterface slot): made
 * with MakeInterface, with the opener's data in front of it (its size and
 * contents are Rust's: rust_opener_size/init/free), its one reference
 * taken here, flagged IFLF_CLONED | IFLF_CLONE_EXPUNGE so DropInterface
 * calls main_Expunge when the opener lets go. The vectors are Roadshow's
 * SocketIFace slots (vectors.c, generated by tools/gen-socket-vectors.py).
 *
 * The first Open starts the stack process and the last Close stops it
 * (rust_lib_open / rust_lib_close); both run in the opener's task, which
 * must be a DOS Process.
 */

#define __NOLIBBASE__
#define __NOGLOBALIFACE__
#include <proto/exec.h>
#include <proto/dos.h>
#include <proto/utility.h>
#include <exec/types.h>
#include <exec/resident.h>
#include <exec/libraries.h>
#include <exec/interfaces.h>
#include <dos/dos.h>
#include <exec/emulation.h>

#ifdef DROPIN
#define LIBNAME    "bsdsocket.library"
#else
#define LIBNAME    "rustsocket.library"
#endif
#define LIBVER     4   /* Roadshow's bsdsocket.library interface, version 4 */
#define LIBREV     3
#define LIBPRI     0
#define VSTRING    LIBNAME " 4.3 (10.11.2026) rustsocket"

/* Read by the amigaos4 crate. */
struct ExecIFace *IExec = NULL;
struct DOSIFace  *IDOS  = NULL;
static struct Library *DOSBase = NULL;
/* CallHookPkt for the hooks openers install (SBTC_ERROR_HOOK and others). */
struct UtilityIFace *IUtility = NULL;
static struct Library *UtilityBase = NULL;

/* SBTC_RELEASESTRPTR: the stack's name and version. */
const char *rs_release_string(void)
{
    return VSTRING;
}

struct MyLibrary {
    struct Library libNode;
    uint16         pad;
    BPTR           segList;
};

extern int32  rust_lib_init(void);
extern int32  rust_lib_open(uint32 count);
extern void   rust_lib_close(uint32 count);
extern int32  rust_lib_busy(void);
extern uint32 rust_opener_size(void);
extern void   rust_opener_init(void *data);
extern void   rust_opener_free(void *data);

extern void *mainVectors[];

/* The opener's data, in front of its interface (MIT_DataSize). */
void *rs_opener_of(struct Interface *self)
{
    return (uint8 *)self - self->Data.NegativeSize;
}

static uint32 _manager_Obtain(struct Interface *self)
{
    return self->Data.RefCount++;
}

static uint32 _manager_Release(struct Interface *self)
{
    return self->Data.RefCount--;
}

/* ---- the per-opener main interface ---- */

uint32 main_Obtain(struct Interface *self)
{
    return self->Data.RefCount++;
}

uint32 main_Release(struct Interface *self)
{
    return self->Data.RefCount--;
}

/* DropInterface at refcount 0: the opener's state goes, then the
   interface. DeleteInterface calls Expunge on an IFLF_CLONED interface, so
   the clone flags are cleared first (else the two recurse). */
APTR main_Expunge(struct Interface *self)
{
    rust_opener_free(rs_opener_of(self));
    self->Data.Flags &= ~(IFLF_CLONED | IFLF_CLONE_EXPUNGE);
    IExec->DeleteInterface(self);
    return NULL;
}

static struct Interface *make_main(struct MyLibrary *lib)
{
    struct TagItem tags[] = {
        { MIT_Name,        (uint32)"main" },
        { MIT_VectorTable, (uint32)mainVectors },
        { MIT_Version,     1 },
        { MIT_DataSize,    rust_opener_size() },
        { MIT_Flags,       IFLF_CLONED | IFLF_CLONE_EXPUNGE },
        { TAG_DONE,        0 }
    };
    struct Interface *i = IExec->MakeInterface((struct Library *)lib, tags);
    if (i) {
        /* MakeInterface does not keep IFLF_CLONED; exec does not Obtain
           what the manager's GetInterface returns. */
        i->Data.Flags |= IFLF_CLONED;
        i->Data.RefCount = 1;
        rust_opener_init(rs_opener_of(i));
    }
    return i;
}

/* ---- the manager ---- */

/* The 68k callers' task table (below) is set up here. */
static APTR map68k_lock;
static struct MyLibrary *theBase;

static struct MyLibrary *libInit(struct MyLibrary *libBase, BPTR segList, struct ExecIFace *iexec)
{
    IExec = iexec;
    libBase->libNode.lib_Node.ln_Type = NT_LIBRARY;
    libBase->libNode.lib_Node.ln_Pri  = LIBPRI;
    libBase->libNode.lib_Node.ln_Name = (STRPTR)LIBNAME;
    libBase->libNode.lib_Flags        = LIBF_SUMUSED | LIBF_CHANGED;
    libBase->libNode.lib_Version      = LIBVER;
    libBase->libNode.lib_Revision     = LIBREV;
    libBase->libNode.lib_IdString     = (STRPTR)VSTRING;
    libBase->segList                  = segList;
    theBase = libBase;
    map68k_lock = IExec->AllocSysObjectTags(ASOT_MUTEX, TAG_DONE);
    if (!map68k_lock) return NULL;
    DOSBase = IExec->OpenLibrary("dos.library", 52);
    if (!DOSBase) return NULL;
    IDOS = (struct DOSIFace *)IExec->GetInterface(DOSBase, "main", 1, NULL);
    if (!IDOS) {
        IExec->CloseLibrary(DOSBase);
        return NULL;
    }
    UtilityBase = IExec->OpenLibrary("utility.library", 52);
    if (UtilityBase)
        IUtility = (struct UtilityIFace *)IExec->GetInterface(UtilityBase, "main", 1, NULL);
    if (!IUtility || rust_lib_init() != 0) {
        if (IUtility) IExec->DropInterface((struct Interface *)IUtility);
        if (UtilityBase) IExec->CloseLibrary(UtilityBase);
        IExec->DropInterface((struct Interface *)IDOS);
        IExec->CloseLibrary(DOSBase);
        return NULL;
    }
    return libBase;
}

static struct MyLibrary *libOpen(struct Interface *self, uint32 version __attribute__((unused)))
{
    struct MyLibrary *libBase = (struct MyLibrary *)self->Data.LibBase;
    libBase->libNode.lib_OpenCnt++;
    libBase->libNode.lib_Flags &= ~LIBF_DELEXP;
    if (rust_lib_open(libBase->libNode.lib_OpenCnt) != 0) {
        libBase->libNode.lib_OpenCnt--;
        return NULL;
    }
    return libBase;
}

static BPTR libExpunge(struct Interface *self);
static BPTR libClose(struct Interface *self);

/* ---- 68k callers (vectors68k.c, CLT_Vector68K) ----

   A 68k program has no interface: it calls the library base's 68k jump
   table with A6 = the base. Each 68k task gets a "main" interface of its
   own at its 68k OpenLibrary (an opener like a PPC one: errno, descriptors,
   break masks), kept here by task, dropped at its last 68k CloseLibrary
   before the library's Close runs. The table is guarded by an exec mutex. */

#define MAP68K 64
static struct { struct Task *task; struct Interface *iface; uint32 count; } map68k[MAP68K];



static struct LibraryManagerInterface *manager_of(struct Library *base)
{
    struct ExtendedLibrary *ext = (struct ExtendedLibrary *)((uint32)base + base->lib_PosSize);
    return ext->ILibrary;
}

static int map68k_find(struct Task *t)
{
    int k;
    for (k = 0; k < MAP68K; k++)
        if (map68k[k].task == t)
            return k;
    return -1;
}

static int map68k_add(struct Task *t, uint32 count)
{
    int k = map68k_find(NULL);
    struct Interface *i;
    if (k < 0 || theBase == NULL)
        return -1;
    i = make_main(theBase);
    if (i == NULL)
        return -1;
    map68k[k].task = t;
    map68k[k].iface = i;
    map68k[k].count = count;
    return k;
}

/* The calling 68k task's interface (made now if it called without opening
   the library itself, e.g. with a base another task opened). */
struct Interface *rs68k_iface(void)
{
    struct Task *t = IExec->FindTask(NULL);
    struct Interface *i = NULL;
    int k;
    IExec->MutexObtain(map68k_lock);
    k = map68k_find(t);
    if (k < 0)
        k = map68k_add(t, 0);
    if (k >= 0)
        i = map68k[k].iface;
    IExec->MutexRelease(map68k_lock);
    return i;
}

uint32 rs68k_open(uint32 *regs)
{
    struct Library *base = (struct Library *)regs[REG68K_A6 / 4];
    struct Task *t;
    int k;
    struct MyLibrary *r = libOpen((struct Interface *)manager_of(base), regs[REG68K_D0 / 4]);
    if (r == NULL)
        return 0;
    t = IExec->FindTask(NULL);
    IExec->MutexObtain(map68k_lock);
    k = map68k_find(t);
    if (k >= 0)
        map68k[k].count++;
    else
        k = map68k_add(t, 1);
    IExec->MutexRelease(map68k_lock);
    if (k < 0) {
        libClose((struct Interface *)manager_of(base));
        return 0;
    }
    return (uint32)r;
}

uint32 rs68k_close(uint32 *regs)
{
    struct Library *base = (struct Library *)regs[REG68K_A6 / 4];
    struct Interface *drop = NULL;
    int k;
    IExec->MutexObtain(map68k_lock);
    k = map68k_find(IExec->FindTask(NULL));
    if (k >= 0 && map68k[k].count <= 1) {
        drop = map68k[k].iface;
        map68k[k].task = NULL;
        map68k[k].iface = NULL;
        map68k[k].count = 0;
    } else if (k >= 0) {
        map68k[k].count--;
    }
    IExec->MutexRelease(map68k_lock);
    /* The opener goes before the library's Close (its sockets close
       through the stack). */
    if (drop)
        IExec->DropInterface(drop);
    return (uint32)libClose((struct Interface *)manager_of(base));
}

uint32 rs68k_expunge(uint32 *regs)
{
    struct Library *base = (struct Library *)regs[REG68K_A6 / 4];
    return (uint32)libExpunge((struct Interface *)manager_of(base));
}

uint32 rs68k_reserved(uint32 *regs __attribute__((unused)))
{
    return 0;
}

static BPTR libClose(struct Interface *self)
{
    struct MyLibrary *libBase = (struct MyLibrary *)self->Data.LibBase;
    libBase->libNode.lib_OpenCnt--;
    rust_lib_close(libBase->libNode.lib_OpenCnt);
    if (libBase->libNode.lib_OpenCnt == 0 && (libBase->libNode.lib_Flags & LIBF_DELEXP))
        return libExpunge(self);
    return ZERO;
}

static BPTR libExpunge(struct Interface *self)
{
    struct MyLibrary *libBase = (struct MyLibrary *)self->Data.LibBase;
    BPTR seg = ZERO;
    /* A process of the library's (the TCP: handler serving files still
       open) runs its code: the library stays until it has gone. */
    if (libBase->libNode.lib_OpenCnt == 0 && !rust_lib_busy()) {
        seg = libBase->segList;
        IExec->Remove((struct Node *)libBase);
        IExec->DropInterface((struct Interface *)IUtility);
        IExec->CloseLibrary(UtilityBase);
        IExec->DropInterface((struct Interface *)IDOS);
        IExec->CloseLibrary(DOSBase);
        IExec->FreeSysObject(ASOT_MUTEX, map68k_lock);
        IExec->DeleteLibrary((struct Library *)libBase);
    } else {
        libBase->libNode.lib_Flags |= LIBF_DELEXP;
    }
    return seg;
}

/* Every GetInterface on the library comes here: "main" version 1 gets a
   new interface for the caller; nothing else is offered (a NULL here is
   final: exec does not look in the library's own list). */
static struct Interface *libGetInterface(struct Interface *self, STRPTR name, uint32 version, struct TagItem *tags __attribute__((unused)))
{
    struct MyLibrary *libBase = (struct MyLibrary *)self->Data.LibBase;
    if (name && name[0] == 'm' && name[1] == 'a' && name[2] == 'i' && name[3] == 'n' && name[4] == 0 && version == 1)
        return make_main(libBase);
    return NULL;
}

static void *libManagerVectors[] = {
    (void *)_manager_Obtain,
    (void *)_manager_Release,
    (void *)0,
    (void *)0,
    (void *)libOpen,
    (void *)libClose,
    (void *)libExpunge,
    (void *)libGetInterface,
    (void *)(APTR)-1,
};

static struct TagItem libManagerTags[] = {
    { MIT_Name,        (uint32)"__library" },
    { MIT_VectorTable, (uint32)libManagerVectors },
    { MIT_Version,     1 },
    { MIT_DataSize,    0 },
    { TAG_DONE,        0 }
};

static uint32 libInterfaces[] = {
    (uint32)libManagerTags,
    0
};

extern const APTR VecTable68K[];

static struct TagItem libCreateTags[] = {
    { CLT_DataSize,   (uint32)sizeof(struct MyLibrary) },
    { CLT_Interfaces, (uint32)libInterfaces },
    { CLT_InitFunc,   (uint32)libInit },
    { CLT_Vector68K,  (uint32)VecTable68K },
    { TAG_DONE,       0 }
};

static const char libName[]    = LIBNAME;
static const char libVString[] = VSTRING;

const struct Resident __attribute__((used)) RomTag = {
    RTC_MATCHWORD,
    (struct Resident *)&RomTag,
    (struct Resident *)&RomTag + 1,
    RTF_NATIVE | RTF_AUTOINIT,
    LIBVER,
    NT_LIBRARY,
    LIBPRI,
    (STRPTR)libName,
    (STRPTR)libVString,
    (APTR)libCreateTags
};

void _start(void)
{
}
